#include "SoundBrowser.h"
SoundBrowser::SoundBrowser(PocketProcessor& p):processor(p) {
    setComponentID("sound-browser");setName("Sound library");
    for(auto* c:std::array<juce::Component*,13>{&bank,&kind,&view,&search,&list,&load,&preview,&favorite,&importBank,&importSamples,&details,&count,&activeSound})addAndMakeVisible(c);
    addAndMakeVisible(root);root.setRange(0,127,1);root.setColour(juce::Slider::textBoxTextColourId,juce::Colour(0xff304a61));root.setSliderStyle(juce::Slider::IncDecButtons);root.setTextBoxStyle(juce::Slider::TextBoxLeft,false,50,24);root.setTooltip("Sampler root MIDI note; does not change the original file.");rootAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(processor.state,"sampleRoot",root);
    addAndMakeVisible(purge);purge.setComponentID("purge-bank");purge.setTooltip("Permanently delete the selected imported bank from disk. All banks removes all imported banks. Factory sounds and source ZIPs are kept.");purge.onClick=[this]{confirmPurge();};
    kind.addItemList({"All sounds","Synthesizers","Samples","Drums / kits"},1);kind.setSelectedId(1);
    view.addItemList({"Presets / variants","Unique samples","Favorites"},1);view.setSelectedId(1);
    search.setTextToShowWhenEmpty("Search name, source or category",juce::Colour(0xff8797a5));search.setComponentID("sound-search");
    bank.onChange=[this]{rebuild();};kind.onChange=[this]{rebuild();};view.onChange=[this]{rebuild();};search.onTextChange=[this]{rebuild();};
    list.setRowHeight(30);list.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xffeef2f6));list.setMultipleSelectionEnabled(false);list.setComponentID("sound-results");
    load.onClick=[this]{loadSelected();};preview.onClick=[this]{audition();};favorite.onClick=[this]{if(!selectedId.isEmpty()){processor.toggleFavorite(selectedId);rebuild();}};
    importBank.onClick=[this]{if(onImportBank)onImportBank();};importSamples.onClick=[this]{if(onImportSamples)onImportSamples();};
    details.setColour(juce::Label::textColourId,juce::Colour(0xff405466));details.setJustificationType(juce::Justification::topLeft);details.setFont(juce::FontOptions(13));
    activeSound.setColour(juce::Label::textColourId,juce::Colour(0xff4a657d));activeSound.setFont(juce::FontOptions(12));
    count.setColour(juce::Label::textColourId,juce::Colour(0xff566b7f));refresh();
}
SoundBrowser::~SoundBrowser(){if(auditionNote>=0)processor.keyboard.noteOff(1,auditionNote,0);}
void SoundBrowser::refresh(){catalog=processor.soundCatalog();juce::String old=bank.getText();bank.clear(juce::dontSendNotification);bank.addItem("All banks",1);juce::StringArray names;for(const auto& s:catalog)names.addIfNotAlreadyThere(s.bank);names.sortNatural();for(int i=0;i<names.size();++i)bank.addItem(names[i],i+2);int oldIndex=names.indexOf(old);bank.setSelectedId(oldIndex<0?1:oldIndex+2,juce::dontSendNotification);rebuild();syncSelection();}
void SoundBrowser::showKind(int value){kind.setSelectedId(value,juce::dontSendNotification);rebuild();}
void SoundBrowser::confirmPurge(){
    const juce::String name=bank.getSelectedId()>1?bank.getText():juce::String{};
    juce::Component::SafePointer<SoundBrowser> safe(this);
    juce::AlertWindow::showOkCancelBox(juce::MessageBoxIconType::WarningIcon,"Permanently purge bank",
        "Delete "+(name.isEmpty()?juce::String("ALL imported banks"):name)+" and their installed sample files?\n\nThe loaded sound is unloaded if it belongs to this bank. Favorites and sound slots are cleared for these sounds. Factory sounds, original WAV/AIFF/ZIP files and already saved projects are kept. Close other instances first. You can reimport the ZIP afterwards.",
        "DELETE FILES","CANCEL",this,juce::ModalCallbackFunction::create([safe,name](int answer){
            if(!safe||answer!=1)return;
            if(safe->auditionNote>=0){safe->processor.keyboard.noteOff(1,safe->auditionNote,0);safe->auditionNote=-1;++safe->auditionGeneration;}
            juce::String error;const bool ok=safe->processor.purgeUserBanks(name,error);safe->refresh();
            if(!ok){if(safe->onError)safe->onError(error);}else safe->details.setText("Installed bank files deleted.\nUse IMPORT BANK to reinstall a fresh copy.",juce::dontSendNotification);
        }));
}
void SoundBrowser::rebuild(){const auto wanted=search.getText().trim().toLowerCase();const int type=kind.getSelectedId(),mode=view.getSelectedId();juce::StringArray samples;rows.clear();for(const auto& sound:catalog){if(bank.getSelectedId()>1&&sound.bank!=bank.getText())continue;if(type==2&&(sound.sample||sound.engine>=4))continue;if(type==3&&!sound.sample)continue;if(type==4&&sound.engine<4)continue;if(mode==3&&!processor.isFavorite(sound.id))continue;if(wanted.isNotEmpty()&&!(sound.name+" "+sound.category+" "+sound.source+" "+sound.variant).toLowerCase().contains(wanted))continue;if(mode==2){if(!sound.sample)continue;auto key=sound.bank+"|"+sound.name+"|"+sound.source;if(samples.contains(key))continue;samples.add(key);}rows.push_back(sound);}purge.setEnabled(std::any_of(catalog.begin(),catalog.end(),[&](const auto& sound){return sound.user>=0&&(bank.getSelectedId()==1||sound.bank==bank.getText());}));list.updateContent();count.setText(juce::String(int(rows.size()))+(mode==2?" unique samples":" sounds"),juce::dontSendNotification);int index=-1;for(size_t i=0;i<rows.size();++i)if(rows[i].id==selectedId){index=int(i);break;}list.selectRow(index);if(index<0){selectedId.clear();details.setText(rows.empty()?"No sounds match these filters.\nImport a bank or add WAV/AIFF samples.":"Select a sound to see its source and variant.\nDouble-click or press LOAD SOUND to play it.",juce::dontSendNotification);}load.setEnabled(index>=0);preview.setEnabled(index>=0);favorite.setEnabled(index>=0);repaint();}
void SoundBrowser::syncSelection(){const auto current=processor.selectedSound();juce::String name=current.isEmpty()?(processor.sampleFrames.load()>0?"Imported / captured sample":"Current sound (unsaved)"):"Project sound (bank not installed)";for(const auto& sound:catalog)if(sound.id==current){name=sound.name+" / "+sound.variant;break;}activeSound.setText("Loaded: "+name,juce::dontSendNotification);if(current.isEmpty())return;for(size_t i=0;i<rows.size();++i)if(rows[i].id==current){list.selectRow(int(i));return;}}
int SoundBrowser::getNumRows(){return int(rows.size());}
void SoundBrowser::paintListBoxItem(int row,juce::Graphics& g,int width,int height,bool selected){if(row<0||row>=int(rows.size()))return;const auto& s=rows[size_t(row)];if(selected){g.setColour(juce::Colour(0xffcbdfea));g.fillAll();}g.setColour(juce::Colour(0xff263e53));g.setFont(juce::FontOptions(13));g.drawText(s.name,12,0,std::max(10,width-350),height,juce::Justification::centredLeft);g.setFont(juce::FontOptions(11));g.setColour(juce::Colour(0xff60798e));g.drawText(s.category,width-330,0,90,height,juce::Justification::centredLeft);g.drawText(view.getSelectedId()==2?"Sample":s.variant,width-235,0,85,height,juce::Justification::centredLeft);g.drawText(s.bank,width-145,0,120,height,juce::Justification::centredLeft);if(processor.isFavorite(s.id)){g.setColour(juce::Colour(0xffcb8129));g.fillEllipse(float(width-17),float(height/2-3),6,6);}}
void SoundBrowser::selectedRowsChanged(int row){if(row<0||row>=int(rows.size()))return;const auto& s=rows[size_t(row)];selectedId=s.id;details.setText(s.name+"\n"+s.category+" / "+s.variant+"\nBank: "+s.bank+"\nSource: "+s.source+(s.sample?"\nSource root: MIDI "+juce::String(s.root,2):s.kit?"\n8 pads: MIDI 60-67 / GM":"\nSynthesized sound"),juce::dontSendNotification);load.setEnabled(true);preview.setEnabled(true);favorite.setEnabled(true);favorite.setButtonText(processor.isFavorite(s.id)?"REMOVE FAVORITE":"ADD FAVORITE");root.setVisible(s.sample);root.setEnabled(selectedId==processor.selectedSound());}
void SoundBrowser::listBoxItemDoubleClicked(int,const juce::MouseEvent&){loadSelected();}
void SoundBrowser::returnKeyPressed(int){loadSelected();}
void SoundBrowser::loadSelected(){if(selectedId.isEmpty())return;juce::String error;if(!processor.loadSound(selectedId,error)){if(onError)onError(error);}else {root.setEnabled(true);syncSelection();if(onLoaded)onLoaded();}}
void SoundBrowser::audition(){if(auditionNote>=0)processor.keyboard.noteOff(1,auditionNote,0);loadSelected();if(processor.selectedSound()!=selectedId)return;const int note=int(processor.state.getRawParameterValue("sampleRoot")->load());auditionNote=note;const auto generation=++auditionGeneration;processor.keyboard.noteOn(1,note,.7f);juce::Component::SafePointer<SoundBrowser> safe(this);juce::Timer::callAfterDelay(350,[safe,note,generation]{if(safe&&safe->auditionGeneration==generation){safe->processor.keyboard.noteOff(1,note,0);safe->auditionNote=-1;}});}
void SoundBrowser::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xffe2e8ef));g.setColour(juce::Colour(0xff304a61));g.setFont(juce::FontOptions(13));g.drawText("SOUND LIBRARY",14,4,160,20,juce::Justification::centredLeft);g.setColour(juce::Colour(0xffbdcad5));g.drawHorizontalLine(66,12,float(getWidth()-12));}
void SoundBrowser::resized(){const int w=getWidth();activeSound.setBounds(190,3,w-370,22);purge.setBounds(w-144,1,130,23);bank.setBounds(14,29,205,28);kind.setBounds(229,29,160,28);view.setBounds(399,29,180,28);search.setBounds(589,29,std::max(100,w-890),28);importBank.setBounds(w-282,29,128,28);importSamples.setBounds(w-144,29,130,28);list.setBounds(14,74,w-360,getHeight()-111);details.setBounds(w-330,75,314,111);root.setBounds(w-325,185,100,24);load.setBounds(w-330,getHeight()-38,115,28);preview.setBounds(w-205,getHeight()-38,100,28);favorite.setBounds(w-213,185,197,25);count.setBounds(14,getHeight()-31,300,20);}
